// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // fuzzed param is an address that the fuzzer will try; property: owner() should equal the stored owner (which was set to address(this) at construction)
    function testFuzz_property(address fuzzed) public {
        // Keep domain wide but avoid the zero address for the fuzzed param not to exclude relevant cases (not required here though)
        // The deciding observation is reading the owner() getter — reference returns the actual owner (address(this)), mutant returns address(0) for all inputs.

        // Call the public owner() and check it returns the deployed owner (address(this)).
        // Use try/catch pattern to also satisfy rule for revert differences (though owner() should not revert).
        bool ok;
        address observed;
        try c.owner() returns (address a) {
            ok = true;
            observed = a;
        } catch {
            ok = false;
            observed = address(0);
        }

        // Single assertion: in the correct contract owner() always reports the stored owner (which was set to address(this) in setUp()),
        // so observed must equal address(this) and call must not have reverted. The mutant that always returns address(0) will fail this for many fuzzed runs.
        assertTrue(ok && observed == address(this));
    }
}

