pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // Fuzz a caller address to check owner() behavior for arbitrary callers
    function testFuzz_property(address caller) public {
        // The reference implementation returns the stored owner (address(this) from constructor)
        // for any caller; that stored owner is non-zero. The mutant returning address(0)
        // would violate this for many callers. We keep domain wide but avoid the zero caller
        // to not conflate with zero-address edge cases.
        vm.assume(caller != address(0));

        // Call owner() as the fuzzed caller to ensure behavior is identical for any caller
        bool ok;
        try c.owner{gas: gasleft()}() returns (address o) {
            // owner() completed
            ok = (o != address(0));
        } catch {
            // if it reverts, mark as failure (reference never reverts here)
            ok = false;
        }

        // Single assertion: for the correct contract, owner() always returns the non-zero owner set at construction;
        // the mutant that always returns address(0) will make this assert fail for many inputs.
        assertTrue(ok);
    }
}

