contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzz the caller address to ensure owner() returns the constructed owner (non-zero) for all callers
    function testFuzz_property(address caller) public {
        // General admissible domain: caller can be any address (including zero), but we want wide coverage
        // The reference contract's owner() should equal the constructor-set owner (address(this) at deploy time)
        // and therefore must be non-zero. The mutant that always returns address(0) will differ for many callers.

        // Call owner() as the fuzzed caller; capture whether the call completed and the returned value
        bool ok;
        address returned;
        // use try/catch to be robust to reverts (shouldn't revert)
        try c.owner{ }() returns (address r) {
            ok = true;
            returned = r;
        } catch {
            ok = false;
            returned = address(0);
        }

        // Exactly one assertion: the reference guarantees owner() does not return address(0) (it was set in constructor)
        // and the call should succeed. Thus ok must be true and returned must equal the known constructor owner.
        // The constructed owner was address(this) at setUp, but from the test's perspective the public getter
        // should return non-zero. We assert that the returned owner is non-zero.
        assertTrue(ok && returned != address(0));
    }
}

