contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), IERC20(address(0)), ICVXBooster(address(0)), new address[](0)); }

    // fuzz a caller address to check that owner() is independent of the caller
    function testFuzz_property(address caller) public {
        // keep caller wide but avoid zero address for clarity (still admissible)
        if (caller == address(0)) caller = address(1);

        // call owner() as the fuzzed caller
        bool ok;
        address returned;
        try c.owner{gas: gasleft()}() returns (address v) {
            ok = true;
            returned = v;
        } catch {
            ok = false;
            returned = address(0);
        }

        // The general rule: owner() should always return the deployer (address(this) from setUp),
        // and must not depend on msg.sender. We therefore assert that calling owner() (from any caller)
        // returns the stored deployer address.
        // We simulate the caller by using vm.prank when possible; but since owner() is view and we
        // invoked it above without prank, ensure behavior is same when called by the fuzzed caller too.
        vm.prank(caller);
        bool ok2;
        address returned2;
        try c.owner{gas: gasleft()}() returns (address v2) {
            ok2 = true;
            returned2 = v2;
        } catch {
            ok2 = false;
            returned2 = address(0);
        }

        // Exactly one assertion: the reference C always reports the same owner regardless of caller.
        // We assert that the two observations (one from default caller and one from the fuzzed caller)
        // are equal and equal to the deployer address (address(this) at setup). This holds for the
        // reference implementation for all inputs; the mutant that returns msg.sender will make these
        // differ for some caller, causing this assertion to fail for those fuzzed inputs.
        assertTrue(ok && ok2 && returned == returned2 && returned == address(this));
    }
}

