import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address possibleOwner) public {
        // Keep domain wide: any address is admissible as a potential owner value
        // The constructor already set owner to address(this). We now check the general rule:
        // For the correct contract, owner() must equal the original owner (constructor value) for all inputs.
        // We read the public owner() getter and assert it equals the constructor-set owner (address(this)).
        // This will hold for the reference; the mutant that returns address(this) from owner() will still
        // return address(this) here (same), so to force a distinguishing input we need to change owner via transferOwnership.
        // Use vm.prank to act as current owner and transfer ownership to a fuzzed address, then verify owner() equals that new owner.

        // Only proceed when possibleOwner is not zero to keep meaningful domain (still wide).
        // Allow zero as well; vm.assume not used to avoid excluding bug-triggering case unnecessarily.

        // Transfer ownership to the fuzzed address using the correct current owner (address(this)).
        vm.prank(address(this));
        c.transferOwnership(possibleOwner);

        // Now read owner() and assert it equals the constructor-set owner we just changed it to (possibleOwner).
        // On the reference contract this holds for all possibleOwner values; on the mutant that returns address(this)
        // owner() will equal address(c) instead of possibleOwner when possibleOwner != address(c), causing the assertion to fail
        // for some fuzz inputs (those where possibleOwner != address(c)).
        address reported = c.owner();
        assertTrue(reported == possibleOwner);
    }
}

