import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), 0, 0, address(this)); }

    // Fuzzed parameter: an arbitrary address that will act as a contract caller
    // General rule: In the reference, only the owner (msg.sender == owner()) can call setOperator; thus
    // a call to setOperator coming from a contract address different from owner must NOT change operator.
    // The mutant that compares owner() to tx.origin can be bypassed by calling through a contract when
    // tx.origin == owner, causing the mutant to allow the call. We fuzz the caller address to be any
    // arbitrary address and ensure it is a contract (by deploying a helper at that address) via create2.
    function testFuzz_property(address arbitrary) public {
        // Keep domain wide but avoid zero address which cannot be a contract deploy target via create2 here
        if (arbitrary == address(0)) return;

        // Deploy a small helper contract at a deterministic address derived from arbitrary so fuzz controls it.
        // We'll use create2 with salt from arbitrary to produce a contract whose deployer is this test contract.
        bytes memory initCode = type(CallerHelper).creationCode;
        bytes32 salt = bytes32(uint256(uint160(arbitrary)));

        address helper;
        assembly {
            helper := create2(0, add(initCode, 0x20), mload(initCode), salt)
        }
        // If deployment failed (unlikely), skip this input
        if (helper == address(0)) return;

        // Set owner to be tx.origin for the attack scenario: deployer (this test) is owner by constructor; transfer ownership to tx.origin (an EOA we control below)
        // Choose an EOA attackerAddr distinct from helper and non-zero. We'll derive it from arbitrary to keep fuzzed.
        address attackerAddr = address(uint160(uint256(keccak256(abi.encodePacked(arbitrary, "attacker")))));
        // Give attackerAddr some ETH so it can be tx.origin in an external prank
        vm.deal(attackerAddr, 1 ether);

        // Transfer ownership from this (current owner) to attackerAddr so attackerAddr is owner()
        c.transferOwnership(attackerAddr);

        // Sanity: owner() now equals attackerAddr
        assert(c.owner() == attackerAddr);

        // Prepare new operator to set; ensure distinct
        address newOp = address(uint160(uint256(keccak256(abi.encodePacked(arbitrary, "newop")))));
        if (newOp == address(0)) return;

        // Now have the helper contract attempt to call c.setOperator(newOp) BUT as an external call with tx.origin == attackerAddr
        // To make tx.origin == attackerAddr, we have attackerAddr perform the external call to helper which will forward the call to c.
        // So attackerAddr does: helper.call(abi.encodeWithSelector(CallerHelper.callSetOperator.selector, address(c), newOp));

        // Prepare calldata for attackerAddr to call helper
        bytes memory payload = abi.encodeWithSelector(CallerHelper.callSetOperator.selector, address(c), newOp);

        // attackerAddr calls helper which will in turn call c.setOperator(...)
        // This means tx.origin == attackerAddr, and msg.sender inside helper == attackerAddr, msg.sender inside c == helper.
        // Reference: onlyOwner checks msg.sender == owner() so it should fail (helper != owner). Mutant checking tx.origin == owner() would allow it.

        // Do the external call from attackerAddr to helper
        vm.prank(attackerAddr);
        (bool ok, ) = helper.call{value: 0}(payload);

        // After call completes, read operator from c and assert the reference property:
        // In the correct contract, since msg.sender (helper) != owner() (attackerAddr), the operator must NOT have been changed to newOp.
        // Thus c.operator() != newOp must hold for all inputs. This single assert will pass on reference for all fuzz inputs,
        // and the mutant (which checks tx.origin == owner()) will allow the helper call to succeed and set operator == newOp for some inputs,
        // causing this assertion to fail.
        assertTrue(c.operator() != newOp);
    }
}

// Helper contract that forwards an external call to setOperator on the target contract
contract CallerHelper {
    // Forward call to target C to set operator
    function callSetOperator(address target, address newOperator) external {
        C(target).setOperator(newOperator);
    }
}

