        // operator must NOT equal newOperator (attacker cannot set operator), regardless of inputs.
        // This property is violated by the mutant for some inputs where tx.origin logic differs.
        assertTrue(c.operator() != newOperator);
    }
}

// Minimal attacker: will call c.setOperator on its own behalf (a contract caller).
contract Attacker {
    C immutable target;
    address immutable who;
    uint256 immutable salt;
    constructor(address _target, address _who, uint256 _salt) {
        target = C(_target);
        who = _who;
        salt = _salt;
    }

    // simply call setOperator as a contract (msg.sender will be this contract)
    function callSetOperator(address newOp) external {
        target.setOperator(newOp);
    }
}

